import assert from "node:assert/strict";
import test from "node:test";
import { addTask, filterTasks, sampleTasks, toggleTask } from "../src/model.mjs";

test("adding a task gives it the next id and an open status", () => {
  const tasks = addTask(sampleTasks, "Plan the offsite");
  assert.deepEqual(tasks.at(-1), { id: 5, title: "Plan the offsite", status: "open" });
});

test("toggling flips one task and leaves the input list alone", () => {
  const tasks = toggleTask(sampleTasks, 1);
  assert.equal(tasks[0].status, "done");
  assert.equal(sampleTasks[0].status, "open");
});

test("filtering defaults to all tasks", () => {
  const tasks = filterTasks(sampleTasks);
  assert.deepEqual(tasks, sampleTasks);
  assert.notEqual(tasks, sampleTasks);
});

test("search matches title substrings without regard to case", () => {
  assert.deepEqual(filterTasks(sampleTasks, "REDIR"), [sampleTasks[1]]);
});

test("search trims surrounding whitespace and treats a blank query as no search", () => {
  assert.deepEqual(filterTasks(sampleTasks, "  ReLeAsE\t"), [sampleTasks[0]]);
  assert.deepEqual(filterTasks(sampleTasks, ""), sampleTasks);
  assert.deepEqual(filterTasks(sampleTasks, " \t\n"), sampleTasks);
});

test("status filtering supports open, done, and all tasks", () => {
  assert.deepEqual(filterTasks(sampleTasks, "", "open"), [sampleTasks[0], sampleTasks[2]]);
  assert.deepEqual(filterTasks(sampleTasks, "", "done"), [sampleTasks[1], sampleTasks[3]]);
  assert.deepEqual(filterTasks(sampleTasks, "", "all"), sampleTasks);
});

test("search and status filters must both match", () => {
  assert.deepEqual(filterTasks(sampleTasks, "THE", "done"), [sampleTasks[1]]);
  assert.deepEqual(filterTasks(sampleTasks, "release", "done"), []);
});

test("filtering handles no matches and empty task lists", () => {
  assert.deepEqual(filterTasks(sampleTasks, "missing task"), []);
  assert.deepEqual(filterTasks([]), []);
  assert.deepEqual(filterTasks([], "release", "open"), []);
});

test("filtering preserves task order and identity without changing the input", () => {
  const input = Object.freeze(sampleTasks.map((task) => Object.freeze({ ...task })));
  const tasks = filterTasks(input, "the", "open");
  assert.deepEqual(tasks, [input[0], input[2]]);
  assert.equal(tasks[0], input[0]);
  assert.equal(tasks[1], input[2]);
  assert.deepEqual(input, sampleTasks);
});

