:root {
  --fg: #1d1d1f;
  --bg: #f5f5f7;
  --border: #d2d2d7;
  --muted: #6e6e73;
}

@media (prefers-color-scheme: dark) {
  :root {
    --fg: #f5f5f7;
    --bg: #1d1d1f;
    --border: #3a3a3c;
    --muted: #98989d;
  }
}

:root[data-theme="light"] {
  --fg: #1d1d1f;
  --bg: #f5f5f7;
  --border: #d2d2d7;
  --muted: #6e6e73;
}

:root[data-theme="dark"] {
  --fg: #f5f5f7;
  --bg: #1d1d1f;
  --border: #3a3a3c;
  --muted: #98989d;
}

body {
  margin: 0;
  font: 16px/1.5 system-ui, sans-serif;
  color: var(--fg);
  background: var(--bg);
}

main {
  max-width: 560px;
  margin: 48px auto;
  padding: 0 16px;
}

form {
  display: flex;
  gap: 8px;
}

input[name="title"] {
  flex: 1;
  padding: 8px 10px;
}

ul {
  padding: 0;
  list-style: none;
}

li {
  display: flex;
  gap: 10px;
  padding: 10px 0;
  border-bottom: 1px solid var(--border);
}

li.done span {
  color: var(--muted);
  text-decoration: line-through;
}

#theme-toggle {
  margin-left: auto;
  background: none;
  border: 1px solid var(--border);
  color: var(--fg);
  border-radius: 6px;
  padding: 4px 8px;
  cursor: pointer;
}

